from pathlib import Path
p=Path('implementation/index.html');old=p.read_text();head=old[:old.index('<style>')];stories=old[old.index('const stories='):old.index("document.querySelector('.close').onclick")]
css='''
:root{color-scheme:dark;--cream:#fae9e5;--muted:#d4bfd5}*{box-sizing:border-box}body{margin:0;background:#211c33;color:var(--cream);font-family:Arial,Helvetica,sans-serif;overflow:hidden}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid #ffd6b9;outline-offset:6px}#viewport{position:fixed;inset:0;overflow:hidden}#scene{position:absolute;transform-origin:center;will-change:transform;transition:transform 1.5s cubic-bezier(.2,.65,.2,1)}#scene img{width:100%;height:100%;display:block;object-fit:fill;pointer-events:none}#shade{position:fixed;inset:0;background:linear-gradient(180deg,#19162635,transparent 45%,#18132630);pointer-events:none}header{position:fixed;z-index:5;inset:0 0 auto;padding:30px 4%;display:flex;justify-content:space-between;align-items:center}.name{font-size:12px;letter-spacing:.12em;text-decoration:none;color:var(--cream)}.quiet{border:1px solid #ead5e22f;background:#241b354d;backdrop-filter:blur(15px);border-radius:30px;padding:11px 18px;font-size:11px;letter-spacing:.05em}.hero{position:fixed;z-index:3;top:17%;left:6%;transition:opacity .7s,transform .7s}h1{font:400 clamp(44px,5vw,80px)/1.1 Georgia,serif;letter-spacing:-.035em;margin:0 0 20px;text-shadow:0 2px 35px #281e4166}.subtitle{font-size:clamp(12px,1.2vw,17px);letter-spacing:.11em;color:#e9d4e7;margin:0}.explore{margin-top:28px;border:1px solid #fce2d366;border-radius:30px;background:#f6d7cce6;color:#392d43;padding:13px 24px;font-size:12px;letter-spacing:.07em;box-shadow:0 6px 30px #4b2c3922}.explore span{margin-left:22px}.entered .hero{opacity:0;transform:translateY(-15px);pointer-events:none}.spot{position:absolute;transform:translate(-50%,-50%);background:transparent;border:0;border-radius:40%;width:13%;height:19%;min-width:44px;min-height:44px}.spot .label{position:absolute;left:50%;top:95%;transform:translateX(-50%);white-space:nowrap;font-size:11px;letter-spacing:.05em;border:1px solid #e6c6d047;background:#211932a6;backdrop-filter:blur(10px);padding:9px 13px;border-radius:25px;transition:background .2s,box-shadow .2s}.spot .label:before{content:'';display:inline-block;width:4px;height:4px;background:#ffd5b7;border-radius:50%;margin-right:8px;box-shadow:0 0 8px #fbbf99}.spot:hover .label,.spot:focus-visible .label{background:#735267d9;box-shadow:0 0 28px #efc1a62e}.spot:hover{background:radial-gradient(ellipse,#ffe3b512,transparent 65%)}footer{position:fixed;z-index:5;bottom:25px;left:4%;right:4%;display:flex;justify-content:space-between;align-items:center;gap:18px}.hint{font-size:10px;letter-spacing:.15em;color:#ecd8e6;text-shadow:0 1px 9px #271b36}.index{font-size:9px;letter-spacing:.16em;color:#d9c2d7}#mobileNav{display:none}.orb{position:fixed;width:6px;height:6px;border-radius:50%;background:#ffe2c6;box-shadow:0 0 10px 3px #ffc4a575,0 0 35px 9px #ffa99525;pointer-events:none;z-index:2;left:51%;top:75%;transition:opacity .2s;opacity:.8}dialog{color:var(--cream);background:#261e35ed;backdrop-filter:blur(25px);border:1px solid #e5bfd63d;border-radius:20px;max-width:440px;width:calc(100% - 36px);padding:35px;box-shadow:0 30px 100px #09051280}dialog::backdrop{background:#100d2440;backdrop-filter:blur(4px)}dialog h2{font:400 34px Georgia,serif;margin:23px 0 16px}dialog p{font-size:14px;line-height:1.8;color:#dfcfdf}dialog a{color:#ffd1b6;font-size:13px;line-height:2}.close{float:right;border:0;background:none;font-size:22px;margin:-16px -10px 0 0}.links{display:flex;gap:16px;flex-wrap:wrap}.eyebrow{font-size:10px;letter-spacing:.2em;color:#eec7b4}.load-failed #scene{display:none}.load-failed .hero:after{content:'The scene could not load. You can still explore through About / links.';display:block;max-width:330px;margin-top:25px;font-size:13px;line-height:1.7}.load-failed .explore{display:none}@media(max-width:650px){header{padding:23px}.name{font-size:10px}.quiet{font-size:10px;padding:10px 13px}.hero{top:16%;left:7%}h1{font-size:44px}.subtitle{font-size:11px;letter-spacing:.06em}.explore{margin-top:22px}footer{bottom:21px;left:22px;right:22px}.index{display:none}.hint{font-size:9px;max-width:180px;line-height:1.8}.spot{display:none}#mobileNav{position:fixed;bottom:100px;left:20px;right:20px;display:flex;justify-content:center;gap:7px;z-index:4;flex-wrap:wrap}#mobileNav button{background:#241c36b8;border:1px solid #e8cdd645;backdrop-filter:blur(12px);border-radius:24px;padding:12px 14px;font-size:11px}.orb{display:none}}@media(prefers-reduced-motion:reduce){*{transition:none!important}.orb{display:none}}
'''
body='''
<div id="viewport"><div id="scene"><img src="assets/pri-world.png" alt="" fetchpriority="high" id="art"><button class="spot" style="left:32%;top:38%" data-story="work" aria-label="Explore AI and work"><span class="label">AI / work</span></button><button class="spot" style="left:59%;top:39%" data-story="speaking" aria-label="Explore speaking"><span class="label">Speaking</span></button><button class="spot" style="left:89%;top:50%" data-story="content" aria-label="Explore content"><span class="label">Content</span></button><button class="spot" style="left:17%;top:61%" data-story="life" aria-label="Explore beyond the screen"><span class="label">Beyond the screen</span></button></div></div><div id="shade"></div><div class="orb" aria-hidden="true"></div>
<header><a class="name" href="/">PRIYANSHI SHAH</a><button class="quiet" id="about">About / links ↗</button></header>
<main><section class="hero" aria-labelledby="title"><h1 id="title">The World of Pri</h1><p class="subtitle">AI scientist, speaker, creator.</p><button class="explore" id="enter">Come explore <span>↗</span></button></section><nav id="mobileNav" aria-label="Explore the world"><button data-story="work">AI / work</button><button data-story="speaking">Speaking</button><button data-story="content">Content</button><button data-story="life">Life</button></nav></main>
<footer><span class="index">A WORLD OF CURIOSITY</span><span class="hint" id="hint">Move to explore · Touch to discover</span><button class="quiet" id="reset" hidden>Back to the view ↗</button></footer>
<dialog id="detail" aria-labelledby="detailTitle"><button class="close" aria-label="Close introduction">×</button><div class="eyebrow" id="category"></div><h2 id="detailTitle"></h2><p id="detailText"></p><div class="links" id="detailLinks"></div></dialog>
'''
js='''
const detail=document.querySelector('#detail');
'''+stories+'''
const scene=document.querySelector('#scene'),art=document.querySelector('#art'),hero=document.querySelector('.hero'),reset=document.querySelector('#reset');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let entered=false,mx=0,my=0;
function layout(){const ratio=(art.naturalWidth||1672)/(art.naturalHeight||941);const w=Math.max(innerWidth,innerHeight*ratio),h=w/ratio;scene.style.width=w+'px';scene.style.height=h+'px';scene.style.left=(innerWidth-w)/2+'px';scene.style.top=(innerHeight-h)/2+'px';paint()}
function paint(){const zoom=entered?1.1:1.015;scene.style.transform=`translate(${mx}px,${my}px) scale(${zoom})`}
art.addEventListener('load',layout);art.addEventListener('error',()=>document.body.classList.add('load-failed'));addEventListener('resize',layout);layout();
addEventListener('pointermove',e=>{if(reduced||innerWidth<650||e.pointerType==='touch')return;mx=(e.clientX/innerWidth-.5)*-14;my=(e.clientY/innerHeight-.5)*-9;paint();const orb=document.querySelector('.orb');orb.style.left=e.clientX+'px';orb.style.top=e.clientY+'px'});
document.querySelector('#enter').onclick=()=>{entered=true;hero.inert=true;document.body.classList.add('entered');reset.hidden=false;reset.focus();paint()};reset.onclick=()=>{entered=false;hero.inert=false;document.body.classList.remove('entered');reset.hidden=true;document.querySelector('#enter').focus();paint()};
document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>openStory(b.dataset.story));document.querySelector('#about').onclick=()=>openStory('about');document.querySelector('.close').onclick=()=>detail.close();detail.addEventListener('click',e=>{if(e.target===detail){const r=detail.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)detail.close()}});
'''
p.write_text(head+'<style>'+css+'</style></head><body>'+body+'<script>'+js+'</script></body></html>')
